begin;
create function pg_temp.recipe(id uuid) returns jsonb language sql as $$ select jsonb_build_object('format','how-many-beers','schemaVersion',1,'type','recipe','id',id,'name','My side','recipe','{"method":"manual","equipment":[],"source":{"kind":"manual"},"steps":[{"id":"mix","type":"instruction","title":"Mix","timing":{"estimatedMinutes":null},"actions":[{"type":"custom"}]}],"phases":[]}'::jsonb) $$;
create function pg_temp.recipe_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.recipe_denied(sql text,label text) returns void language plpgsql as $$declare denied boolean:=false;begin begin execute sql;exception when others then denied:=true;end;if not denied then raise exception 'FAIL allowed: %',label;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000001',0,'b1400000-0000-4000-8000-000000000001','save',pg_temp.recipe('a1400000-0000-4000-8000-000000000001'));
select pg_temp.recipe_ok(jsonb_array_length(public.list_personal_recipes(auth.uid())->'recipes')=1,'recipe listed');
select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000001',0,'b1400000-0000-4000-8000-000000000001','save',pg_temp.recipe('a1400000-0000-4000-8000-000000000001'));
select pg_temp.recipe_ok((select revision=1 from public.personal_recipes limit 1),'retry creates once');
select pg_temp.recipe_denied($q$select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000001',0,'b1400000-0000-4000-8000-000000000002','save',pg_temp.recipe('a1400000-0000-4000-8000-000000000001'))$q$,'stale revision');
select pg_temp.recipe_denied($q$select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000001',1,'b1400000-0000-4000-8000-000000000001','save',pg_temp.recipe('a1400000-0000-4000-8000-000000000001'))$q$,'operation substitution');
select pg_temp.recipe_denied($q$select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000002',0,'b1400000-0000-4000-8000-000000000002','save',jsonb_set(pg_temp.recipe('a1400000-0000-4000-8000-000000000002'),'{recipe,events}','[]'))$q$,'execution leak');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.recipe_ok(jsonb_array_length(public.list_personal_recipes(auth.uid())->'recipes')=0,'other owner cannot list active recipe');
select pg_temp.recipe_denied($q$select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000001',1,'b1400000-0000-4000-8000-000000000008','remove')$q$,'other owner cannot remove active recipe');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000001',1,'b1400000-0000-4000-8000-000000000003','remove');
select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000001',1,'b1400000-0000-4000-8000-000000000003','remove');
select pg_temp.recipe_ok(jsonb_array_length(public.list_personal_recipes(auth.uid())->'recipes')=0,'removed recipe hidden');
select pg_temp.recipe_denied($q$select public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000001',1,'b1400000-0000-4000-8000-000000000004','save',pg_temp.recipe('a1400000-0000-4000-8000-000000000001'))$q$,'stale save cannot resurrect');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.recipe_ok((select count(*)=0 from public.personal_recipes),'owner isolation');
select pg_temp.recipe_denied($q$select public.list_personal_recipes('00000000-0000-4000-8000-000000000001')$q$,'owner impersonation');
select pg_temp.recipe_denied($q$delete from public.personal_recipes$q$,'no direct delete');
reset role;
select pg_temp.recipe_ok((select state='deleted' and deleted_at is not null and document->>'name'='My side' from public.personal_recipes where id='a1400000-0000-4000-8000-000000000001'),'underlying recipe retained');
rollback;
